    "Tỷ lệ tương phản nền & lớp kính chữ đang cân bằng, hiển thị mượt trên cả 6 Tab.": "背景コントラストと文字ガラスカードの透過度が最適に調整され、全6タブで滑らかに表示されています。",
    "Độ sáng video đang cao và lớp phủ tối rất thấp — nên kéo \"Độ tối phủ nền\" lên 20%–40% để chữ luôn dễ đọc.": "映像の輝度が高く暗막オーバーレイが低すぎます — 文字を読みやすくするため「背景の暗さ」を20%〜40%に上げてください。",
    "Thẻ chữ đang rất trong suốt trên video rõ nét — có thể tăng nhẹ \"Độ nhòe\" (4–8px) nếu thấy rối mắt.": "鮮明な映像上で文字カードが非常に透明になっています — 見づらい場合は「ぼかし」（4〜8px）を少し上げてください。",
    "Nền đang khá tối và mờ — hãy kéo \"Độ rõ video\" lên ~80% để cảm nhận chuyển động khung cảnh tốt hơn.": "背景が暗く薄くなっています — 映像の動きをより楽しむには「映像の不透明度」を約80%に引き上げてください。",
