    "# HỒ SƠ KHUNG STORY BIBLE — THỂ LOẠI TRINH THÁM NOIR / BÍ ẨN": "# ストーリーバイブル構造フレーム — ノワール探偵・ミステリー",
    "- Bối cảnh trung tâm: Tháp Đồng Hồ Đêm Mưa & Thành phố Cảng Sương Mù.": "- 中心舞台：雨夜の時計塔と霧の港町。",
    "- Quy luật thời gian: Chuông đồng chỉ rung khi có sự cố chuyển giao ký ức hoặc mở khóa tầng áp mái.": "- 時間の掟：青銅の鐘は記憶同期の異変時、または屋根裏の解錠時にのみ鳴り響く。",
    "- Giọng văn chủ đạo: Noir tiết chế, giàu chi tiết giác quan (mưa, đồng thau, giấy da, ánh đèn bão).": "- 主導文体：抑制の効いたノワール調、豊かな五感描写（雨、真鍮、羊皮紙、嵐のランタンの灯り）。",
    "=== TỔNG HỢP STORY BIBLE CHÍNH THỨC (BẢN MẪU GUEST MODE) ===": "=== 公式ストーリーバイブル統合（ゲストモードサンプル） ===",
    "1. Bối cảnh & Luật ngầm:": "1. 舞台背景と裏の掟：",
    "- Vụ hỏa hoạn 20 năm trước thực chất là màn che đậy cho cuộc thử nghiệm lưu trữ ký ức của Giáo sư Hoàng tại Tháp Đồng Hồ.": "- 20年前の火災は、実は時計塔で行われたホアン教授の記憶保存実験を隠蔽するための偽装だった。",
    "- Con số 13:00 trên mặt đồng hồ không chỉ thời gian mà là mã khóa cơ học nối lên gác chuông.": "- 文字盤の13:00は時刻ではなく、鐘楼最上階へと繋がる機械式暗号である。",
    "2. Tuyến nhân vật chính:": "2. 主要キャラクター陣：",
    "- Trần Minh Khôi (Chính): Thám tử lưu trữ, có vết sẹo cũ ở cổ tay trái, luôn giữ đồng hồ quả quýt vỡ kính.": "- チャン・ミン・コイ（主人公）：記録保管庫の探偵。左手首に古傷があり、ガラスの割れた懐中時計を常に携えている。",
    "- Lệ Băng (Đồng hành / Nghi phạm): Người giữ chùm chìa khóa đồng La Mã, nắm nửa sự thật về vụ hỏa hoạn.": "- レ・バン（相棒／容疑者）：ローマ数字の刻まれた青銅の鍵束の番人であり、火災事件の真相の半分を握る。",
    "- Bé Miu (Nhân chứng bí ẩn): Xuất hiện trong hầm kín dù cửa khóa ngoài, cầm mảnh đồng khắc tên Giáo sư Hoàng.": "- ミウちゃん（謎の目撃者）：外から施錠された地下室に突如現れ、ホアン教授の名が刻まれた銅片を手にしている。",
    "- Giáo sư Hoàng (Phản diện giấu mặt): Tác giả chuỗi sổ cái bìa đen và cỗ máy đồng bộ xung chuông.": "- ホアン教授（黒幕）：6冊の黒革台帳と鐘パルス記憶同期装置の設計者。",
    "3. Mạch phục bút đang chạy:": "3. 進行中の伏線スレッド：",
    "- Chìa khóa thứ tư hình bán nguyệt úp ngược -> Mở két sắt tầng áp mái.": "- 逆さ三日月紋が刻まれた第4の鍵 -> 屋根裏の金庫を開ける。",
    "- Vết thương cổ tay trái của Minh Khôi cộng hưởng với tần số chuông đồng.": "- ミン・コイの左手首の古傷が青銅の鐘の周波数と共鳴する。",
    "Nhân vật chính (Thám tử lưu trữ)": "主人公（記録保管庫の探偵）",
    "Điềm tĩnh, quan sát tỉ mỉ chi tiết cơ học, ám ảnh công lý bị chôn vùi.": "冷静沈着で機械構造の細部を鋭く観察し、葬られた正義の解明に執念を燃やす。",
    "Ngắn gọn, sắc bén, dùng ngôi \"Tôi\" — gọi Lệ Băng bằng chức danh hoặc tên.": "簡潔で鋭く、一人称は「私」— レ・バンを役職または名前で呼ぶ。",
    "Người giữ khóa Tháp Đồng Hồ": "時計塔の鍵守",
    "Lạnh lùng bên ngoài nhưng cố bảo vệ bằng chứng gốc trước thế lực giấu mặt.": "外見は冷淡だが、背後の勢力から元の証拠を密かに守り抜こうとしている。",
    "Mỉa mai nhẹ, hay đặt câu hỏi ngược để dò thái độ.": "軽い皮肉を交え、相手の出方を探るために逆質問を投げかけることが多い。",
    "Nhân chứng bí ẩn": "謎の目撃者",
    "Nhạy bén với âm thanh bánh răng, xuất hiện tại những nơi tưởng chừng kín bưng.": "歯車の音に敏感で、密閉されているはずの場所に神出鬼没に現れる。",
    "Ngây thơ nhưng câu nào cũng chứa ẩn ý cảnh báo.": "無邪気な口調だが、すべての言葉に警告の含みが秘められている。",
    "Phản diện giấu mặt": "背後に潜む黒幕",
    "Lập dị, tôn sùng việc \"khắc thời gian vào đồng thau\".": "風変わりな性格で、「真鍮に時間を刻むこと」を狂信的に崇めている。",
    "Trang trọng, học thuật qua các trang sổ cái để lại.": "残された台帳の記述は荘厳かつ学術的な文体で貫かれている。",
    "13:00 là mã khóa gác chuông chứ không phải giờ cháy": "13:00は出火時刻ではなく鐘楼の解錠暗号である",
    "Lệ Băng, Giáo sư Hoàng (Minh Khôi chỉ mới suy ra ở Chương 3)": "レ・バン、ホアン教授（ミン・コイは第3章で初めて推理）",
    "Giới cảnh sát thành phố & nhân viên viện lưu trữ": "市警察および記録保管院の職員たち",
    "Đường thông gió bí mật sau giá sách tầng hầm nối thẳng xuống bờ sông": "地下室の本棚裏にある秘密の通気口が川岸へ直結している",
    "Trần Minh Khôi và Lệ Băng": "チャン・ミン・コイとレ・バン",
    "Vết sẹo cổ tay trái của Minh Khôi là dấu tích của chiếc vòng đồng thử nghiệm đầu tiên": "ミン・コイの左手首の傷跡は最初の試作青銅リングの刻印である",
    "Giáo sư Hoàng, Lệ Băng": "ホアン教授、レ・バン",
    "Trần Minh Khôi (cấm AI để lộ quá sớm trước Chương 5!)": "チャン・ミン・コイ（第5章より前にAIがネタバレすることを厳禁！）",
    "Chìa khóa thứ tư khắc vệt bán nguyệt úp ngược": "逆さ三日月紋が刻まれた第4の鍵",
    "Trùng khớp mảnh giấy cháy dở tại viện lưu trữ, dùng mở két tầng áp mái.": "保管院で見つかった焼け残りの紙片と一致し、屋根裏の金庫を開けるのに使われる。",
    "Con búp bê thiếu một chiếc cúc mắt & mảnh đồng tên Giáo sư Hoàng": "片方のボタンの目が欠けた人形とホアン教授の名が刻まれた銅片",
    "Cúc mắt bị rơi bên trong rãnh trượt cánh cửa thông gió bí mật.": "欠けたボタンの目は秘密の通気扉のスライド溝の中に落ちている。",
    "Cổ tay trái của Minh Khôi nhói theo tần số chuông đồng": "ミン・コイの左手首が青銅の鐘の周波数に合わせて疼く",
    "Chứng minh Minh Khôi từng trực tiếp có mặt trong phòng máy năm xưa.": "ミン・コイがかつて時計塔の機械室に居合わせていたことを証明する。",
    "Chương 2": "第2章",
