    "Bé Miu": "ミウちゃん",
    "Giáo sư Hoàng": "ホアン教授",
    "một luồng điện chạy dọc sống lưng, ánh mắt phức tạp, thở dài một tiếng, khẽ nhếch môi, không khỏi cảm thán": "背筋を走る電流, 複雑な眼差し, ため息をつく, 唇の端をわずかに上げる, 感嘆せずにはいられない",
    "một luồng điện chạy dọc sống lưng, thở dài một tiếng, ánh mắt phức tạp, khẽ nhếch môi tạo thành một vòng cung, không khỏi cảm thán trong lòng, trong lòng dâng lên một cảm giác khó tả, bầu không khí bỗng trở nên tĩnh lặng đến đáng sợ, nụ cười nửa miệng đầy ẩn ý": "背筋を走る電流, ため息をつく, 複雑な眼差し, 唇がわずかに弧を描く, 心の中で感嘆する, 言いようのない感情が込み上げる, 空気が突然不気味なほど静まり返る, 意味深な片笑み",
