    "Ví dụ: Viết xong cao trào Chương 5, chỉnh tâm lý nhân vật...": "例：第5章のクライマックスを書き終えた、キャラの心理描写を調整...",
    "Lấy thời điểm nhạc đang phát hiện tại làm Điểm A": "現在再生中の音楽位置をA地点に設定",
    "Lấy thời điểm nhạc đang phát hiện tại làm Điểm B": "現在の再生位置を B 地点に設定",
    "Đánh dấu đoạn nhạc cao trào này cho phân cảnh đang viết": "執筆中のシーンにこのクライマックス区間をマーク",
    "Cân bằng hoàn hảo giữa tốc độ gõ chữ và nhịp giữ sức bền mắt.": "タイピング速度と目の持久ペースの完璧なバランス。",
    "Tuyệt chiêu vượt qua \"hội chứng trang trắng\" — chỉ cần gõ liên tục 15 phút.": "「白紙症候群」を突破する奥義——15分間ノンストップで書き続けるだけ。",
    "Dành cho phân cảnh tâm lý nặng hoặc đối thoại dài cần giữ mạch cảm xúc liền.": "感情の流れを途切れさせたくない重厚な心理描写や長い会話シーン向け。",
    "Chu kỳ sinh học 90 phút để hoàn tất trọn vẹn một chương Light Novel 3.500+ từ.": "3,500語以上のライトノベル1話を丸ごと書き上げる90分の生体集中サイクル。",
    "Thụt lề dòng đầu tiên kiểu sách in": "書籍風の段落1行目字下げ",
    "Tạm làm mờ các khung chữ xuống 14% để bạn ngắm trọn 100% ảnh nền / hiệu ứng": "テキスト枠を一時的に14%まで薄くし、背景画像やエフェクトを100%堪能できます",
    "Hình nền & hiệu ứng hiện rõ vừa vặn, khung viết chữ vẫn cực kỳ êm mắt.": "背景とエフェクトが程よく見えつつ、執筆エリアも目に優しいままです。",
    "Hiển thị trọn vẹn 90% màu sắc tranh nền, ảnh hoặc video cá nhân.": "背景イラストや画像、個人動画の色合いを90%鮮やかに表示します。",
    "Làm dịu ánh nền phía sau bản thảo cho phiên viết sâu sau nửa đêm.": "深夜の集中執筆のために原稿背後の光を和らげます。",
    "Kéo sang phải để hình nền/tranh nghệ thuật hiện rõ rực rỡ hơn; kéo sang trái để khung chữ đậm hơn khi đọc lâu.": "右へ動かすと背景やイラストがより鮮やかに、左へ動かすと長時間の読書向けに文字枠が濃くなります。",
    "Giữ nguyên màu ảnh/video gốc độ nét cao.": "高画質な写真・動画の元の色合いを維持します。",
