    "mod09 (Lưu 3 tầng & Sức Khỏe mở rộng kèm Chân dung Author \"đang theo dõi bạn\"), mod27 (Bi Số 8 3D + Chat Kép), mod28 (Video Hướng Dẫn ~10 Phút Chi Tiết + Nhật Ký), mod29 (6 Tab + Cài App PWA 4 thẻ 1-c": "mod09 (3層保存＆「あなたを見守る」作者ポートレート付き拡張ウェルネス), mod27 (3D マジック8ボール＋デュアルチャット), mod28 (約10分の詳細解説動画＋更新履歴), mod29 (6タブ＋ワンタップPWAインストールカード4種…)",
