    "Tất cả thao tác gộp tệp, tách chương, đóng gói .ZIP hay dựng tệp .PDF thuần nhị phân đều xử lý ngay tại trình duyệt của bạn —": "ファイル結合、チャプター分割、.ZIP 圧縮、純粋なバイナリ .PDF 生成はすべてブラウザ内で直接処理されます —",
    "an toàn tuyệt đối, không upload truyện lên server trung gian": "仲介サーバーへ小説をアップロードしないため完全に安全です",
