    "📂 Chọn Nhiều Tệp Từ Máy (.PDF / .TXT / .MD / .HTML) Để Gộp Hoặc Tách Chương:": "📂 結合または話数分割するローカルファイルを複数選択 (.PDF / .TXT / .MD / .HTML):",
    "File chỉ đọc vào RAM cục bộ. Bạn có thể chọn cùng lúc nhiều file PDF/TXT để gộp hoặc đóng gói.": "ファイルはローカルRAMにのみ読み込まれます。複数のPDF/TXTを同時に選んで結合・パッケージ化できます。",
