    "💾 Viết bản thảo, Tự lưu 3 tầng, Undo & Time-Machine": "💾 原稿執筆、3層自動保存、元に戻す＆Time-Machine",
    "Dữ liệu nằm hoàn toàn trong RAM, localStorage, IndexedDB và thư mục ổ cứng của bạn (0 byte gửi lên server trung gian).": "データはすべてRAM、localStorage、IndexedDB、ローカルドライブフォルダ内に保持されます（仲介サーバーへの送信は0バイト）。",
    "📅 Điểm danh 7 ngày, Huy hiệu, Pomodoro & Nhạc thiên nhiên WebAudio": "📅 7日間チェックイン、バッジ、Pomodoro＆WebAudio自然音",
    "Đồng hồ đếm ngược, tiếng mưa rơi/suối/lò sưởi tổng hợp trực tiếp bằng chip âm thanh WebAudio và chuỗi ngày viết lưu tại trình duyệt.": "カウントダウンタイマー、WebAudioで直接合成される雨音・せせらぎ・暖炉の音、連続執筆日数はブラウザに保存されます。",
    "🎨 Khung trang sách, 60FPS Hình nền & Kho tranh nghệ thuật": "🎨 本のページ枠、60FPS背景＆アートギャラリー",
    "Toàn bộ hạt chuyển động Canvas 60FPS và bộ lọc ánh sáng bảo vệ mắt được GPU trình duyệt dựng ngay lập tức khi mất mạng.": "すべてのCanvas 60FPSパーティクルとアイケア光フィルターは、オフライン時もブラウザGPUが即座に描画します。",
    "📦 Đóng gói .ZIP, .DOCX chuẩn OOXML, .EPUB, .TXT & Tạo/Gộp .PDF trong RAM": "📦 RAM上で .ZIP、OOXML準拠 .DOCX、.EPUB、.TXT の出力＆.PDF生成・結合",
    "Hoạt động theo mô hình client-side giống iLovePDF: tệp của bạn được CPU & RAM tại máy đọc, cắt ghép và tải thẳng về Downloads, không upload.": "iLovePDFと同様のクライアント側モデルで動作し、ローカルのCPUとRAMで読み取り・分割結合してアップロードなしでDownloadsへ直接保存します。",
    "🔍 Quét sáo rỗng (Cliche), Tìm BM25 RAG & Cắt file tiểu thuyết thành chương": "🔍 陳腐表現(Cliche)スキャン、BM25 RAG検索＆小説の章分割",
    "Tách hàng trăm nghìn từ thành từng chương riêng biệt vào Tab 2 hoặc tìm chi tiết cũ bằng thuật toán nội bộ chỉ trong vài mili-giây.": "内蔵アルゴリズムにより数ミリ秒で何十万語もの小説をタブ2の個別チャプターに分割したり、過去の描写を検索できます。",
