    "Phải kết nối Internet để gửi prompt trực tiếp từ trình duyệt của bạn tới máy chủ API Google Generative Language bằng API Key riêng.": "ご自身のAPI Keyを使い、ブラウザからGoogle Generative Language APIサーバーへプロンプトを直接送信するにはネット接続が必要です。",
    "🏛️ Tóm tắt Story Bible bằng AI & Đối chiếu AI Diff nâng cao": "🏛️ AI ストーリーバイブル要約＆高度なAI Diff比較",
    "Phần phân tích ngôn ngữ chuyên sâu cần mạng gọi Gemini; khi mất mạng hệ thống vẫn tự trích xuất từ khóa cơ bản tại máy.": "高度な言語分析にはGeminiを呼び出すネット接続が必要ですが、オフライン時も基本キーワードのローカル抽出は動作します。",
    "☁️ Tải dự án lên Google Drive (OAuth) & Mở Google NotebookLM": "☁️ Google Drive (OAuth) へプロジェクトをアップロード＆Google NotebookLMを開く",
    "Cần Internet để xác thực Google OAuth cá nhân, đồng bộ file .ZIP sang Drive hoặc làm việc trên NotebookLM đám mây.": "個人のGoogle OAuth認証、.ZIPのDrive同期、クラウド版NotebookLMの利用にはネット接続が必要です。",
    "📊 Gửi Báo Lỗi tự động về Google Sheets 2 cột (Apps Script Web App)": "📊 2列のGoogle Sheetsへバグ報告を自動送信 (Apps Script Web App)",
    "Cần mạng để gọi webhook HTTPS của Google Apps Script; nếu mất mạng, báo lỗi vẫn được cất vào hộp thư cục bộ chờ gửi sau.": "Google Apps ScriptのHTTPS Webhook呼び出しに通信が必要ですが、オフライン時はローカル送信トレイに保存され後で送信されます。",
