    "Ngăn hành vi History Back ngoài vùng nhập liệu và giữ nguyên trang Studio đang mở.": "入力領域外での History Back 動作を防ぎ、開いているスタジオ画面をそのまま維持します。",
    "Nút bấm thiếu type=\"button\" hoặc nhấn Enter gây Submit Form": "type=\"button\" がないボタンや Enter キーによる Submit Form 発生",
    "Button không khai báo type mặc định thành submit khiến trình duyệt tải lại URL ?.": "type 未指定のボタンはデフォルトで submit となり、ブラウザが URL ? を再読み込みしてしまいます。",
    "Quét DOM Sweep liên tục ép type=\"button\" và chặn submit mặc định trên toàn ứng dụng.": "継続的な DOM Sweep スキャンにより、アプリ全体で type=\"button\" を強制しデフォルト送信を阻止します。",
    "Ghi đè UI / mất tiêu điểm con trỏ lúc Autosave hoặc Backup": "Autosave や Backup 時の UI 上書き・カーソルフォーカス消失",
    "Chu kỳ lưu 3 tầng hoặc mở modal kiểm tra làm mất vị trí con trỏ văn bản đang gõ.": "3層保存サイクルや確認モーダルの表示により、入力中のカーソル位置が失われます。",
    "FocusAndCaretRecoveryEngine lưu snapshot selectionStart/End/scrollTop và phục hồi an toàn.": "FocusAndCaretRecoveryEngine が selectionStart/End/scrollTop のスナップショットを保存し安全に復元します。",
    "Service Worker controllerchange tự tải lại trang giữa lúc gõ": "Service Worker の controllerchange が入力中にページを自動リロードする問題",
