    "ServiceWorkerPassiveUpdateCoordinator trì hoãn làm mới cho tới khi tác giả đồng ý.": "ServiceWorkerPassiveUpdateCoordinator が作者の承認まで更新による再読み込みを保留します。",
    "Đóng nhầm tab khi bản thảo chưa kịp xả xong xuống 3 tầng lưu": "原稿が3層ストレージへ書き込まれ切る前に誤ってタブを閉じた場合",
    "Author vừa gõ dở câu cuối và vô tình nhấn Ctrl+W hoặc đóng cửa sổ.": "最後の文の入力途中で誤って Ctrl+W を押すかウィンドウを閉じてしまった場合です。",
    "DirtyStateBeforeUnloadProtector ghi ngay bản sao lưu khẩn cấp tức thì trong <5ms.": "DirtyStateBeforeUnloadProtector が <5ms 未満で即座に緊急バックアップを書き込みます。",
