    "“Ánh đèn huỳnh quang nhấp nháy cắt ngang sống mũi hắn, hắt một vệt bóng xám dài xuống mặt bàn gỗ.”": "「明滅する蛍光灯の光が彼の鼻筋を横切り、木製の机に長い灰色の影を落とした。」",
    "Hoảng hốt kìm nén": "抑え込んだ動揺",
    "“Đầu ngón tay đang giữ quai tách khẽ khựng lại, làm gợn sóng nhỏ trong lòng chén trà sậm màu.”": "「ティーカップの持ち手を握る指先がかすかに止まり、濃いお茶の表面に小さな波紋が広がった。」",
    "Cô độc / Lạnh lẽo đô thị": "孤独・都会の冷たさ",
    "“Ánh neon từ biển hiệu đối diện rỉ qua khe rèm chớp, nhuộm xanh bệ cửa sổ ẩm sương.”": "「向かいの看板のネオンがブラインドの隙間から漏れ出し、夜露で湿った窓辺を青く染めた。」",
    "Ngỡ ngàng sững sờ": "唖然とした驚き",
    "“Đồng tử mở to hơn bình thường một chút, phản chiếu nguyên vẹn ngọn lửa nhỏ đang rung trước gió.”": "「瞳孔が普段よりわずかに見開かれ、風に揺れる小さな炎をそのまま映し出していた。」",
    "Kiệt sức sau biến cố": "異変の後の疲労困憊",
    "“Quầng thâm mờ dưới mi mắt khiến cái chớp mắt của cô chậm hơn bình thường nửa nhịp.”": "「まぶたの下のうっすらとした隈のせいで、彼女のまばたきは普段より半拍遅れていた。」",
    "Cảnh giác tột độ": "極度の警戒",
    "“Ánh nhìn quét nhanh qua khe cửa khép hờ, dừng đúng hai giây ở vệt bùn mới in cạnh thảm chùi chân.”": "「視線が半開きのドアの隙間を素早くかすめ、玄関マットの脇に残った新しい泥跡の上できっかり二秒止まった。」",
    "🌦️ Bối Cảnh Thời Tiết & Ánh Sáng Điện Ảnh (Chèn Nhanh Mở Cảnh)": "🌦️ シネマティックな天候＆光影背景（シーン導入クイック挿入）",
    "🌧️ Mưa đêm & Đèn đường": "🌧️ 夜の雨と街灯",
