    "Giải đáp chi tiết cách dùng 6 Màn hình, Duyệt màu Google Docs, Biểu đồ Chế độ 5, Phiên bản Tab 6 và Xuất PDF chọn Font!": "6つの画面、Google Docs 風カラー添削、モード5のチャート、Tab 6 のバージョン管理、フォント指定 PDF 書き出しの使い方を詳しく解説します！",
