    "Khi bạn đã nhập API Key ở Tab 6, mình sẽ đọc luôn chương bạn đang viết và Story Bible để bàn luận cốt truyện trực tiếp cùng bạn!": "Tab 6 で API Key を入力すると、執筆中の章とストーリーバイブルを読み取って直接プロットの相談に乗ります！",
