    "Mode 2: Tán gẫu thoải mái, hỏi tính năng web hoặc bàn bạc ý tưởng truyện...": "Mode 2：気楽に雑談したり、機能について質問したり、物語のアイデアを相談したり…",
    "🎬 Video Hướng Dẫn Toàn Diện 44 Module (~10 Phút, Phụ Đề Song Ngữ Ngoài Khung Hình) & Nhật Ký v44.0": "🎬 全44モジュール総合ガイド動画（約10分・枠外バイリンガル字幕付き）＆ v44.0 更新履歴",
    "🎬 Video Hướng Dẫn (Có Phụ Đề Tiếng Việt)": "🎬 チュートリアル動画（ベトナム語字幕付き）",
    "📜 Nhật Ký Đại Tu & Vá Lỗi v38.0": "📜 v38.0 大規模改修＆バグ修正ログ",
    "🤖 Chọn Mô Hình Gemini Up-to-Date": "🤖 最新 Gemini モデルを選択",
    "⌨️ Phím Tắt & Mẹo Điện Thoại / PC": "⌨️ ショートカット＆スマホ / PC のコツ",
    "⛶ Xem toàn màn hình": "⛶ 全画面で見る",
    "Cổng Kết Nối & Nút Ủng Hộ Đăng • Entry Gate & Creator Bar": "接続ゲート & Đăng 応援ボタン • Entry Gate & Creator Bar",
    "CỔNG KẾT NỐI · TẢI APP PWA · MOD 01-05 · MOD 29-30": "接続ゲート · PWA アプリ入手 · MOD 01-05 · MOD 29-30",
    "🇻🇳 Chào mừng bạn tới Bi's Novel Writing Studio với bộ biểu tượng chân dung mới! Ngay đầu cổng là nút Mai Hải Đăng (Bi), nút to Ủng hộ Đăng và nút Tải App về thiết bị ngay.": "🇻🇳 新しいポートレートアイコンセットを搭載した Bi の小説執筆スタジオへようこそ！ゲート最上部には Mai Hải Đăng (Bi) ボタン、大きな Đăng を応援ボタン、今すぐアプリをインストールボタンが並んでいます。",
    "🔇 Giọng Việt: TẮT": "🔇 ベトナム語音声：OFF",
