    "⚙️ Tab 6: Kho Phiên Bản, Xuất Sách & Hệ Thống": "⚙️ Tab 6：バージョン履歴、書籍書き出し＆システム",
    "🎱 Trợ Lý Viên Bi Số 8 (Chatbot & Phím Tắt Nổi)": "🎱 8番ボールアシスタント（チャットボット＆フローティングボタン）",
    "📱 Giao Diện Điện Thoại / Máy Tính Bảng (Responsive)": "📱 スマホ / タブレット画面（レスポンシブ）",
