    "2. Bạn đang gặp lỗi gì?": "2. どのような問題が起きていますか？",
    "3. Nó trông như thế nào? (Mô tả hiện tượng / chọn thẻ nhanh bên dưới)": "3. どのような状態ですか？（現象の説明 / 下のクイックタグを選択）",
