    "Đính kèm thông số kỹ thuật an toàn (Màn hình, Tab, Trình duyệt — Không gửi API Key hay truyện)": "安全な環境情報を添付（画面・タブ・ブラウザ情報のみ — API Key や本文は送信しません）",
    "🧹 Xóa nháp": "🧹 下書きをクリア",
    "📨 Gửi Báo Lỗi Ngay": "📨 今すぐバグ報告を送信",
    "📋 Biên nhận báo lỗi đã ghi nhận gần đây:": "📋 最近記録されたバグ報告の受付控え：",
    "📊 Kết Nối Google Sheet 2 Cột (Apps Script)": "📊 2列 Google Sheet 連携（Apps Script）",
    "⬇️ Tải nhật ký lỗi (.JSON)": "⬇️ バグログをダウンロード (.JSON)",
    "📊 Thiết Lập Gửi Báo Lỗi Thẳng Về Google Sheets 2 Cột (Thời gian | Nội dung Bug)": "📊 2列の Google Sheets へバグ報告を直接送信する設定（日時 | バグ内容）",
    "Tạo Google Sheets có 2 cột ở dòng 1 (": "1行目に2列ある Google Sheets を作成し（",
    "), mở": "）、",
    "Tiện ích mở rộng → Apps Script": "拡張機能 → Apps Script",
    ", dán đoạn mã dựng sẵn bên dưới và Triển khai dạng Web App (": "を開いて下のテンプレートコードを貼り付け、ウェブアプリとしてデプロイ（",
    ") rồi dán link": "）してから、リンクを",
    "vào ô này:": "この欄に貼り付けてください：",
    "💾 Lưu URL Apps Script": "💾 Apps Script URL を保存",
    "📋 Chép Mã Apps Script 2 Cột (Sheet)": "📋 2列用 Apps Script コードをコピー（Sheet）",
    "✅ Đã nhúng cứng sẵn kênh Google Sheets 2 cột mặc định — bấm \"Gửi Báo Lỗi Ngay\" là tự động ghi dòng mới.": "✅ 標準の2列 Google Sheets 連携が組み込まれています — 「今すぐバグ報告を送信」を押すだけで新しい行に自動記録されます。",
    "🔍 Tự Chẩn Đoán Máy": "🔍 端末セルフ診断",
    "📊 Xuất .CSV": "📊 .CSV 書き出し",
    "📄 Xuất .TXT": "📄 .TXT 書き出し",
    "🧹 Dọn lịch sử": "🧹 履歴を消去",
    "Chưa có báo lỗi nào được ghi nhận từ phiên làm việc của bạn.": "現在のセッションではまだバグ報告が記録されていません。",
    "🩺 Gợi Ý Tự Kiểm Tra Nhanh Theo Triệu Chứng:": "🩺 症状別のクイック自己診断ガイド：",
    "Khóa Gemini API chưa xác thực được hoặc báo hết hạn mức": "Gemini API キーが認証できない、またはクォータ切れになる",
    "Bấm nút Mở Google AI Studio ở Bước 1 để sao chép lại nguyên vẹn mã khóa bắt đầu bằng AIzaSy... hoặc AQ....": "ステップ1の「Google AI Studio を開く」ボタンから AIzaSy... または AQ... で始まるキーをそのままコピーし直してください。",
    "Thử bấm Tự Động Kiểm Tra Bằng Gemini Flash-Lite khi kết nối mạng ổn định.": "安定したネット接続環境で「Gemini Flash-Lite で自動チェック」をお試しください。",
    "Trong trường hợp viết dài vượt hạn mức API, dùng nút Copy Prompt Tổng sang Gemini Web hoặc đổi về Gemini Flash.": "長文執筆で API クォータを超えた場合は、統合プロンプトをコピーして Gemini Web を使うか、Gemini Flash に切り替えてください。",
    "Chọn thư mục ổ cứng không nhận hoặc không thấy lưu tệp": "ローカルフォルダが認識されない、またはファイルが保存されない",
    "Tạo một thư mục riêng ngoài Desktop hoặc ổ D (ví dụ D:\\TruyenCuaToi) rồi chọn lại.": "デスクトップ外や D ドライブなどに専用フォルダ（例：D:\\TruyenCuaToi）を作成して再選択してください。",
    "Bấm Cho phép chỉnh sửa tệp khi Chrome hoặc Edge hiện cửa sổ hỏi quyền.": "Chrome や Edge で権限確認のポップアップが出たら「ファイルの編集を許可」をクリックしてください。",
    "Kiểm tra tình trạng lưu ở nút Tự Lưu 3 Tầng tại góc trái thanh trên cùng.": "上部バー左端の「3層自動保存」ボタンで保存状態を確認してください。",
    "Đang gõ văn bản hoặc nhấn Backspace thì trang bị tải lại": "文字入力中や Backspace キー押下時にページが再読み込みされる",
    "Luôn lưu thư mục truyện tách riêng khỏi thư mục mã nguồn HTML.": "小説の保存フォルダは常に HTML ソースコードのフォルダと分けてください。",
    "Module 36 (Zero-Reload Save Shield) đang tự động chặn tín hiệu reload từ WebSocket và sự kiện form/navigation.": "Module 36（Zero-Reload Save Shield）が WebSocket やフォーム/遷移イベントによる再読み込み信号を自動ブロックしています。",
    "Bấm Kiểm tra Khiên Chống Reload ở cuối Tab 6 để xem số lượt tải lại đã được chặn an toàn.": "Tab 6 下部の「リロード防止シールドを確認」を押すと、安全にブロックされた再読み込み回数を確認できます。",
    "Đóng cửa sổ báo lỗi": "バグ報告ウィンドウを閉じる",
    "Ví dụ: Thanh tiêu đề Tab 2, Nút lọc Nháp, Ô chọn Font Tab 5...": "例：Tab 2 ヘッダーバー、下書きフィルタボタン、Tab 5 フォント選択欄…",
    "Mô tả điều bạn đã bấm hoặc gõ và điều sai lệch xảy ra (Ví dụ: Mình bấm lọc Nháp nhưng vẫn hiện cả chương Đã duyệt...)": "クリックや入力した操作と発生した不具合を記述してください（例：下書きフィルタを押したのに承認済みの章も表示されたままになる…）",
    "Ví dụ: Chữ vàng trên nền xám khó đọc, hai nút đè viền lên nhau, trang tự load lại về cổng kết nối...": "例：灰色の背景に黄色の文字が読みづらい、2つのボタンの枠線が重なっている、ページが接続ゲートに勝手にリロードされる…",
    "Đã nhúng sẵn kênh Google Sheet mặc định (chỉ điền nếu muốn ghi đè URL khác)": "既定の Google Sheet チャンネルが組み込み済みです（別 URL で上書きする場合のみ入力）",
    "Gõ từ khóa (API, thư mục, đè chữ, reload, markdown)...": "キーワードを入力（API、フォルダ、文字重なり、リロード、markdown）…",
    "👑 MODULE 35 · TÁC GIẢ SPOTLIGHT": "👑 MODULE 35 · 作者スポットライト",
    "Ghi Công Tác Giả (Mai Hải Đăng — Bi) & Kết Nối": "作者クレジット（Mai Hải Đăng — Bi）＆連絡先",
    "Lời tâm sự 3 ngày làm web cùng AI của tác giả, bảng ghi công nổi bật tự động cuộn & kênh liên hệ trực tiếp.": "AI と共に3日間で Web サイトを作り上げた作者の想い、自動スクロールのクレジットロール＆直接連絡先。",
