    "Bạn đã gõ những con chữ đầu tiên trong Studio. Mọi đại tiểu thuyết đều bắt đầu từ dòng chữ thứ nhất.": "スタジオで最初の文字を刻みました。すべての大作は最初の一行から始まります。",
