    "📜 Chương Đã Chốt Dấu": "📜 確定済みの章",
    "Ít nhất 1 chương đã được Approve & Lock Draft và đồng bộ vào hệ thống Story Bible.": "少なくとも1章が Approve & Lock Draft を完了し、ストーリーバイブルに同期されました。",
    "Yêu cầu: 1,500 từ · 1 chương đã duyệt": "達成条件：1,500語 · 承認済み 1章",
    "🖋️ Nhịp Bút Bền Bỉ": "🖋️ 揺るぎない筆致",
    "Vượt mốc 10.000 từ với 3 chương hoàn chỉnh — tương đương hồi mở màn của một bộ Light Novel thực thụ.": "完成した3章で10,000語を突破 — 本格的なライトノベルの序章に匹敵するボリュームです。",
    "Yêu cầu: 10,000 từ · 3 chương đã duyệt": "達成条件：10,000語 · 承認済み 3章",
    "🏛️ Kiến Trúc Sư Thế Giới": "🏛️ 世界の建築家",
    "Trên 30.000 từ — lúc này Story Bible, Ma trận Ai Biết Gì và Phục bút đã phát huy tối đa uy lực.": "30,000語超え — ここでストーリーバイブル、情報共有マトリックス、伏線が最大限の威力を発揮します。",
    "Yêu cầu: 30,000 từ · 6 chương đã duyệt": "達成条件：30,000語 · 承認済み 6章",
