    "Đạt dung lượng 1 quyển Light Novel hoàn chỉnh! Hãy dùng Tab 6 xuất sách DOCX / PDF lưu giữ thành quả.": "ライトノベル1巻分のボリュームに到達しました！Tab 6 から DOCX / PDF で書籍書き出しして成果を残しましょう。",
    "Yêu cầu: 60,000 từ · 10 chương đã duyệt": "達成条件：60,000語 · 承認済み 10章",
    "🌌 Đại Tự Sự Vượt Mọi Giới Hạn": "🌌 限界を超えた大叙事詩",
    "Hơn 120.000 từ — Mai Hải Đăng xin gửi lời chúc mừng nồng nhiệt nhất tới sự kiên trì phi thường của bạn!": "120,000語突破 — Mai Hải Đăng からあなたの並外れた粘り強さへ最大の祝福をお送りします！",
