    "Kiểm tra API Key": "API Key を確認",
    "vẫn chạy bình thường.": "などの機能は通常どおり動作します。",
    "🔑 Google Drive API Key (Kiểm định kết nối Drive & Flash-Lite)": "🔑 Google Drive API Key（Drive＆Flash-Lite 接続検証）",
