    "🛡️ OAuth 2.0 Client ID (Bắt buộc để ghi folder lên Drive)": "🛡️ OAuth 2.0 Client ID（Drive へのフォルダ作成に必須）",
    "Mở quyền": "権限を有効化",
    "Bất kỳ ai có link đều xem được": "リンクを知っている全員が閲覧可能",
