    "Đặt tên cho thư mục làm việc của bạn. Tên này sẽ áp dụng cho cả tệp .ZIP tải về máy lẫn thư mục mới tạo trên Google Drive.": "作業フォルダの名前を設定します。この名前はローカルに保存する .ZIP ファイルと Google Drive 上の新規フォルダの両方に適用されます。",
    "Đóng gói toàn bộ Chương truyện, Story Bible, Nhân vật, Đầu ra 5 Chế độ AI và file khôi phục vào 1 tệp .ZIP chuẩn tải ngay về thiết bị.": "すべての章、ストーリーバイブル、キャラクター、5つの AI モード出力、復元データを1つの標準 .ZIP ファイルにまとめて端末へ直接ダウンロードします。",
    "Chọn tệp .ZIP hoặc .JSON bạn đã tải từ máy cũ để khôi phục toàn bộ dự án sang máy mới ngay lập tức.": "以前の端末で保存した .ZIP または .JSON ファイルを選択し、新しい端末へプロジェクト全体を即座に復元します。",
    "Dán AIza... (từ Google Cloud Credentials)": "AIza... を貼り付け（Google Cloud Credentials から取得）",
    "Kiểm tra Google Drive API Key thực tế qua internet và test độ sẵn sàng của Gemini Flash-Lite.": "インターネット経由で Google Drive API Key を実テストし、Gemini Flash-Lite の利用可能状態を確認します。",
    "Đăng nhập tài khoản Google cá nhân trên trình duyệt (chỉ cấp quyền drive.file cho thư mục Studio tạo).": "ブラウザで個人の Google アカウントにログインします（スタジオが作成したフォルダのみに drive.file 権限を付与）。",
    "Tạo thư mục theo tên bạn nhập trên Google Drive, tải lên toàn bộ bản thảo + tệp .ZIP và tạo link chia sẻ.": "入力した名前で Google Drive 上にフォルダを作成し、全原稿＋.ZIP ファイルをアップロードして共有リンクを生成します。",
    "🎬 BƯỚC 1 / 2 • KẾT NỐI VIDEO YOUTUBE VÀO RẠP VIẾT TRUYỆN": "🎬 ステップ 1 / 2 • 執筆シアターに YouTube 動画を接続",
    "Hướng Dẫn Copy Link YouTube (Trên Máy Tính & Điện Thoại)": "YouTube リンクのコピー方法（PC・スマホ対応）",
    "Không cần đăng nhập, không mất tab viết truyện. Chỉ cần sao chép link video YouTube bạn thích rồi dán vào ô dưới — hệ thống tự động nhận diện và chuyển sang": "ログイン不要、執筆タブも失われません。お気に入りの YouTube 動画リンクをコピーして下の欄に貼り付けるだけで、システムが自動認識して",
    "ngay lập tức!": "へ即座に切り替えます！",
    "🚀 Chưa có sẵn đường link trong khay nhớ tạm?": "🚀 まだクリップボードにリンクがありませんか？",
    "Bấm nút bên cạnh để mở trang chủ YouTube ở tab mới, tìm video muốn nghe/làm hình nền rồi copy link quay lại đây.": "横のボタンを押して新しいタブで YouTube を開き、聴きたい曲や背景にしたい動画を見つけてリンクをコピーし、ここへ戻ってください。",
    "▶ Mở YouTube.com Ngay": "▶ 今すぐ YouTube.com を開く",
    "Cách lấy link trên Máy Tính (PC/Mac)": "パソコン（PC/Mac）でのリンク取得方法",
    "Mở video, nhạc lo-fi, playlist hoặc cảnh mưa 4K bạn muốn xem.": "見たい動画、lo-fi 音楽、プレイリスト、または 4K 雨音映像などを開きます。",
    "Cách lấy link trên Điện Thoại": "スマートフォンでのリンク取得方法",
    "Mở ứng dụng YouTube (hoặc trình duyệt) trên iPhone / Android.": "iPhone / Android で YouTube アプリ（またはブラウザ）を開きます。",
    "🔗 Dán Link Video hoặc Playlist YouTube vào đây (Tự động chạy ngay Bước 2 khi link hợp lệ):": "🔗 YouTube 動画またはプレイリストのリンクをここに貼り付け（有効なリンクなら自動でステップ2へ進みます）：",
    "📋 Dán Nhanh": "📋 クイック貼付",
    "▶ Vào Bước 2 Ngay": "▶ 今すぐステップ2へ",
    "Hỗ trợ đủ link:": "あらゆるリンク形式に対応：",
    ", hoặc link có kèm giờ phát": "、または再生開始時間付きのリンク",
    "Ghi chú Privacy-Enhanced:": "プライバシー強化モードに関する注記：",
    "Hệ thống phát video qua máy chủ rút gọn": "動画は簡素化ホスト",
    "giúp giảm tối đa giao diện gây phân tâm xung quanh (cột bình luận, đề xuất). Lưu ý nếu chủ kênh YouTube khóa quyền nhúng bên thứ 3 hoặc bạn mở web trực tiếp bằng giao thức": "経由で再生され、周囲の集中を妨げる要素（コメント欄、おすすめ）を最小限に抑えます。なお、YouTube チャンネル側で外部埋め込みを制限している場合や、ページを",
    ", khung Bước 2 sẽ hiện sẵn nút mở sang YouTube trong 1 chạm.": "プロトコルで直接開いている場合は、ステップ2のパネルにワンタップで YouTube を開くボタンが表示されます。",
    "Đóng bảng hướng dẫn Bước 1": "ステップ1案内パネルを閉じる",
    "Đóng hướng dẫn Bước 1": "ステップ1のガイドを閉じる",
    "Ví dụ: https://www.youtube.com/watch?v=... hoặc https://youtu.be/...": "例：https://www.youtube.com/watch?v=... または https://youtu.be/...",
    "🗺️ Bản Đồ Tính Năng Guest Mode (Dùng Thử vs Cần Kết Nối)": "🗺️ ゲストモード機能マップ（お試し利用 vs 要接続）",
    "Mọi thao tác trong Guest Mode hoàn toàn an toàn, chỉ chạy tạm trên RAM và không lưu ổ cứng.": "ゲストモードでの操作はすべて完全に安全で、RAM 上でのみ一時実行され、ディスクには保存されません。",
