    "Toàn Trang": "サイト全体",
    "Điều hướng 6 Tab trên PC & Điện thoại + Giao diện Sáng/Tối + Zen Focus": "PC・スマホ対応 6 タブ切り替え + ライト／ダークテーマ + Zen Focus",
    "Chuyển mượt cả 6 màn hình, mở thanh công cụ rút gọn, xem đồ thị & phản hồi responsive.": "6 つの画面をスムーズに切り替え、コンパクトツールバーの開閉、グラフ表示、レスポンシブ表示を体験できます。",
    "Đọc bản thảo mẫu, Thống kê từ, Quét sáo ngữ AI, Từ điển Ngũ quan, Chuẩn hóa thoại, Đồ thị quan hệ SVG & Duyệt Diff thử trên RAM": "サンプル原稿の閲覧、文字数統計、AI 陳腐表現スキャン、五感辞典、セリフ整形、SVG 相関図＆RAM 上での Diff レビュー体験",
    "Tương tác mọi công cụ biên tập trên bộ chương mẫu trong phiên hiện tại (không ghi lên ổ cứng).": "現在のセッション内でサンプル章に対しあらゆる編集ツールを試せます（ディスクへは書き込まれません）。",
    "Chuyển chương mẫu, Lọc Trạng thái Nháp/Duyệt & Tra cứu BM25 (0 Token)": "サンプル章の切り替え、下書き／承認済み絞り込み＆BM25 検索（0 Token）",
    "Tìm kiếm tức thời mọi tình tiết trong bộ tiểu thuyết mẫu \"Bí Mật Tháp Đồng Hồ Đêm Mưa\".": "サンプル小説『雨夜の時計塔の秘密』のあらゆる展開を即座に検索できます。",
    "🧪 PROMPT MẪU MÔ PHỎNG (KHÔNG ĐƯỢC TỰ NHẬP)": "🧪 シミュレーション用サンプルプロンプト（自由入力不可）",
    "Chạy 10 Prompt Mẫu & Kết Quả Mô Phỏng Cho Đủ 5 Chế Độ (Mode 1 → 5) + Hỏi Mẫu Bi Số 8": "全 5 モード（Mode 1 → 5）対応のサンプルプロンプト 10 選＆シミュレーション結果の実行 + Bi #8 サンプル質問",
    "Chặn tự gõ câu lệnh mới; chỉ cần bấm chọn Prompt mẫu là xem trọn quy trình tổng hợp Prompt, Google Docs Diff, Đánh giá độc giả và Biểu đồ SVG Mode 5.": "新規プロンプトの手入力は制限されますが、サンプルプロンプトを選ぶだけで、プロンプト構築・Google Docs Diff・読者評価・Mode 5 SVG グラフの一連の流れを確認できます。",
    "Xem Hồ sơ Story Bible mẫu, Ma trận \"Ai Biết Gì\", Sổ Phục bút & Copy Prompt Google NotebookLM": "サンプルのストーリーバイブル設定、知識マトリックス「誰が何を知っているか」、伏線台帳の閲覧＆Google NotebookLM 用プロンプトコピー",
    "Kiểm tra đầy đủ cấu trúc chống quên cốt truyện và sao chép câu lệnh NotebookLM miễn phí.": "ストーリー忘れ防止構造を隅々まで確認し、NotebookLM 用プロンプトを無料でコピーできます。",
    "Pomodoro đồng bộ 2 chiều, Nhạc A–B & Âm thanh mưa, YouTube Không Quảng Cáo Tìm Trong Khung & Nền Video Chuyển Động 16:9": "双方向同期 Pomodoro、A–B リピート音楽＆雨音、広告なし枠内 YouTube 検索＆16:9 モーション動画背景",
    "Trải nghiệm trọn vẹn không gian viết sâu, nến sáng & lịch điểm danh tạm trên RAM.": "深い執筆空間、灯るキャンドル、RAM 上の一時出席カレンダーを存分に体験できます。",
    "Video Hướng Dẫn Tương Tác, Bách Khoa Toàn Thư Chức Năng (Mod 31), Xem Trước Xuất Sách PDF & Thông Tin Tác Giả": "インタラクティブ動画ガイド、機能百科事典（Mod 31）、PDF 書籍書き出しプレビュー＆著者情報",
    "Tìm hiểu toàn bộ các module và thử trình xem trước bố cục sách PDF chọn font chữ.": "全モジュールを把握し、フォント選択付きの PDF 書籍レイアウトプレビューを試せます。",
    "🔐 KHÓA — CẦN GEMINI API KEY": "🔐 ロック中 — GEMINI API KEY が必要",
    "Tự gõ Prompt AI mới, Chạy Gemini AI thật, Đồng bộ Story Bible bằng AI & Chat tự do Viên Bi Số 8": "AI プロンプト自由入力、実際の Gemini AI 実行、AI によるストーリーバイブル同期＆Bi #8 フリートーク",
    "Cần dán Gemini API Key ở màn hình chính để gọi mô hình thật (Flash-Lite, Flash, Pro, Hydrogen 4).": "実際のモデル（Flash-Lite、Flash、Pro、Hydrogen 4）を呼び出すには、メイン画面で Gemini API Key を貼り付ける必要があります。",
