    "Lưu bản thảo xuống ổ cứng / IndexedDB, Tạo chương mới, Nhập file .DOCX/.PDF, Xóa chương, Kho Phiên Bản & Đồng bộ .ZIP / Google Drive": "原稿をディスク／IndexedDB に保存、新規章作成、.DOCX/.PDF 読み込み、章の削除、バージョン保管庫＆.ZIP／Google Drive 同期",
