    "⌨️ Đã tắt Chế độ Máy Đánh Chữ.": "⌨️ タイプライターモードをオフにしました。",
    "⚠️ Chương hiện tại đang trống, chưa có câu thoại để chuẩn hóa.": "⚠️ 現在のチャプターは空のため、書式統一するセリフがありません。",
    "✨ Tuyệt vời! Văn bản & câu thoại chương này đã gọn chuẩn sẵn rồi.": "✨ 完璧です！このチャプターの本文とセリフはすでにきれいに整っています。",
    "📱 Các đoạn văn hiện tại đã có độ dài thoáng đẹp trên điện thoại!": "📱 現在の段落はスマホでも読みやすいちょうどよい長さになっています！",
    "✨ Toàn bộ chương Bản Nháp đã được căn chuẩn sẵn.": "✨ すべての下書きチャプターはすでに整列済みです。",
    "🎯 Đã nhảy tới đúng cụm từ cần trau chuốt trong bản thảo!": "🎯 原稿内のブラッシュアップが必要なフレーズへ移動しました！",
