    "📕 Đang mở hộp thoại Lưu Sách .PDF với Font & Cỡ chữ đã chọn!": "📕 選択したフォント＆文字サイズで .PDF 書籍保存ダイアログを開いています！",
    "⚠️ Chưa có chương nào để gộp PDF cho NotebookLM!": "⚠️ NotebookLM 用 PDF に結合できるチャプターがまだありません！",
    "⚠️ Không có chương nào để xuất file .TXT!": "⚠️ .TXT ファイルに書き出せるチャプターがありません！",
    "⚠️ Không có chương nào để xuất file .DOCX!": "⚠️ .DOCX ファイルに書き出せるチャプターがありません！",
    "🔊 Đã bật chế độ đọc giọng Tiếng Việt cho Trợ lý Viên Bi Số 8!": "🔊 Bi 8ボールアシスタントのベトナム語音声読み上げをオンにしました！",
    "💬 Hãy nhập câu hỏi hoặc ý tưởng bạn muốn bàn bạc nhé!": "💬 相談したい質問やアイデアを入力してください！",
    "📋 Đã sao chép câu trả lời của Viên Bi Số 8!": "📋 Bi 8ボールの回答をコピーしました！",
    "📥 Đã chèn nội dung từ phòng Chat vào cuối Bản thảo Tab 1!": "📥 チャットルームの内容をタブ1の原稿末尾に挿入しました！",
    "🏛️ Đã lưu ý tưởng vào Hồ sơ Story Bible (Tab 4)!": "🏛️ アイデアをストーリーバイブル設定（タブ4）に保存しました！",
    "💡 Đã lưu ý tưởng vào Bảng Trắng Nháp Nhanh!": "💡 アイデアをクイックスクラッチパッドに保存しました！",
    "🗑️ Đã làm mới phòng trò chuyện Viên Bi Số 8!": "🗑️ Bi 8ボールのチャットルームをリセットしました！",
    "⚠️ Trình duyệt hiện tại không hỗ trợ Web Speech TTS.": "⚠️ 現在のブラウザは Web Speech TTS に対応していません。",
    "🔊 Đang đọc bằng giọng Việt tự nhiên...": "🔊 自然なベトナム語音声で読み上げ中...",
    "⚠️ Trình duyệt chưa cài giọng Tiếng Việt (đã chặn đọc bằng giọng Anh). Mở bằng Microsoft Edge để dùng giọng Việt tự nhiên!": "⚠️ このブラウザにはベトナム語音声がインストールされていません（英語音声での代読をブロックしました）。自然なベトナム語音声を使うには Microsoft Edge で開いてください！",
    "🔊 Đang đọc nội dung bằng giọng Tiếng Việt...": "🔊 ベトナム語音声で内容を読み上げ中...",
    "⚠️ Chưa có nội dung hội thoại để xuất.": "⚠️ 書き出せる会話内容がまだありません。",
    "📥 Đã tải xuống Nhật ký bàn luận cốt truyện (.TXT)!": "📥 プロット相談ログ（.TXT）をダウンロードしました！",
    "↺ Đã đưa các thanh & màn hình thu gọn nổi về lại vị trí gốc!": "↺ すべてのフローティングバーと最小化パネルを初期位置へ戻しました！",
    "Mẹo bảo vệ bản thảo: Bạn có thể bấm \"Ổ cứng\" hoặc sao lưu .JSON ở Tab 2 để lưu thêm 1 bản trên máy.": "原稿保護のヒント：タブ2の「ハードディスク」または .JSON バックアップを使えば、端末にもう1つ控えを保存できます。",
    "⚠️ Chưa thấy nội dung Prompt Tổng Hợp để copy! Hãy bấm \"Tổng hợp Prompt Tổng\" trước nhé.": "⚠️ コピーできる統合プロンプトがまだありません！先に「統合プロンプトを生成」を押してください。",
    "⚠️ Trình duyệt chưa cấp quyền clipboard — bạn hãy bôi đen khung Prompt Tổng và nhấn Ctrl+C nhé!": "⚠️ ブラウザのクリップボード権限がありません — 統合プロンプト欄を選択して Ctrl+C を押してください！",
    "📥 Đã xuất bảng lịch sử Điểm danh & Năng suất viết (.CSV) về máy!": "📥 出席チェック＆執筆生産性ログ（.CSV）を端末に書き出しました！",
    "📝 Đã lưu ghi chú điểm danh hôm nay!": "📝 本日のチェックインメモを保存しました！",
    "🧋 Cảm ơn bạn đã ủng hộ Hải Đăng! Đang mở mã VietQR TPBank...": "🧋 Hải Đăng へのご支援ありがとうございます！VietQR TPBank コードを開いています...",
    "📂 Hãy chọn ít nhất 1 tệp (.txt/.md/.pdf) trước khi gộp.": "📂 結合する前に、少なくとも1つのファイル（.txt/.md/.pdf）を選択してください。",
    "📂 Hãy chọn các tệp (.pdf / .txt / .md) cần gom gói .ZIP trước.": "📂 先に .ZIP パックへまとめるファイル（.pdf / .txt / .md）を選択してください。",
    "⚠️ Hãy chọn tệp truyện hoặc có nội dung ở bàn viết trước khi chạy bộ tách chương cục bộ.": "⚠️ ローカルチャプター分割を実行する前に、小説ファイルを選択するか執筆デスクに本文を入力してください。",
    "Nhập 01:25 rồi bấm Enter hoặc chạm/click ra ngoài để tự xác nhận (A < B ≤ thời lượng)": "01:25 のように入力して Enter を押すか枠外をタップ／クリックすると自動確定されます（A < B ≤ 再生時間）",
    "💡 Vì sao là \"Web Viết Tiểu Thuyết Của Bi\"? Tên gọi \"Bi\" chính là nickname ở nhà thân mật của tác giả Mai Hải Đăng — đặt tên như vậy để góc sáng tác luôn giữ cảm giác gần gũi như ở nhà mình vậy.": "💡 なぜ「Bi の小説執筆スタジオ」という名前なのですか？「Bi」は作者 Mai Hải Đăng の家族からの親しみある愛称です — この創作の場がいつでも自分の家のように温かく居心地のよい場所であり続けるように名付けました。",
    "Bấm nút Mở YouTube.com Ngay phía trên.": "上の「今すぐ YouTube.com を開く」ボタンを押してください。",
    "Click chuột vào thanh địa chỉ trình duyệt, nhấn Ctrl + C (hoặc bấm nút Chia sẻ / Share ➔ Sao chép dưới video).": "ブラウザのアドレスバーをクリックして Ctrl + C を押します（または動画下の「共有 / Share」➔「コピー」をクリック）。",
    "Quay lại đây và dán (Ctrl + V) vào ô xanh bên dưới!": "ここに戻り、下の緑色の入力欄に貼り付け（Ctrl + V）してください！",
    "Chạm nút Chia sẻ (Share) nằm ngay bên dưới khung video.": "動画枠のすぐ下にある「共有（Share）」ボタンをタップします。",
    "Chọn mục Sao chép đường dẫn (Copy link).": "「リンクをコピー（Copy link）」を選択します。",
    "Quay lại Tab 5 của Web Viết Tiểu Thuyết và bấm nút 📋 Dán từ Clipboard hoặc nhấn giữ vào ô nhập để Dán!": "小説執筆スタジオのタブ5に戻り、「📋 クリップボードから貼付」ボタンを押すか、入力欄を長押しして貼り付けてください！",
