    "Tab 6 (Xuất & Kho)": "Tab 6（書出＆保管庫）",
    "Thanh nổi & Bi #8": "フローティングバー＆Bi #8",
    "▾ Cổng Xác Thực Gemini API Key Qua Flash-Lite & Link AI Studio 1-Click": "▾ Flash-Lite による Gemini API Key 認証ポータル＆ワンクリック AI Studio リンク",
    "Mở Cổng / Kiểm Tra Key & Thư Mục": "ポータルを開く / Key＆フォルダ確認",
    "🕒 Dùng khi nào:": "🕒 使用タイミング：",
    "Mỗi lần mở web lần đầu tiên, khi đổi tài khoản Google AI Studio mới hoặc khi vừa quay lại trình duyệt để rà soát nhanh trạng thái Key trước lúc sáng tác.": "初回起動時や新しい Google AI Studio アカウントへの切替時、または執筆前にブラウザへ戻って Key 状態を素早く確認したいときに使います。",
    "📋 Các bước thực hiện chuẩn:": "📋 標準手順：",
    "Bấm nút \"Mở Google AI Studio Để Copy API Key Ngay\" để lấy khóa AIza... hoặc AQ... từ tài khoản Google của bạn.": "「Google AI Studio を開いて API Key をすぐコピー」ボタンから Google アカウントの AIza... または AQ... キーを取得します。",
    "Dán khóa vào ô nhập liệu; hệ thống tự động gọi mô hình Flash-Lite nhẹ nhất để kiểm tra sống-chết mà không tốn đáng kể hạn mức.": "入力欄にキーを貼り付けると、最軽量の Flash-Lite モデルを自動呼び出しして利用枠をほとんど消費せず疎通確認を行います。",
    "Nếu trước đó bạn đã lưu Key và Thư mục, Cổng kết nối vẫn hiện lại ngắn gọn để bạn rà soát và bấm nút xanh lá vào Studio.": "以前 Key とフォルダを保存済みの場合も、接続ポータルに簡潔な確認画面が表示され、緑のボタンで Studio へ入れます。",
    "💡 Mẹo tác giả:": "💡 作者のヒント：",
    "Bạn có thể mở lại Cổng kết nối bất kỳ lúc nào ngay trong Tab 6 bằng nút \"Kiểm Tra / Đổi Key & Thư Mục Kết Nối\" để thay Key mới mà không cần tải lại trang.": "Tab 6 の「Key・接続フォルダを確認 / 変更」ボタンからいつでも接続ポータルを開き直し、ページ再読み込みなしで新しい Key へ切り替えられます。",
    "▸ Chọn & Ghi Nhớ Thư Mục Làm Việc Trên Ổ Cứng (Hỗ Trợ Cả PC Lẫn Điện Thoại)": "▸ ローカル作業フォルダの選択＆記憶（PC・スマホ両対応）",
