    "Đi tới nút Tìm & Thay Thế": "検索＆置換ボタンへ移動",
    "▸ Chế Độ Tập Trung Toàn Màn Hình (Zen Mode) & Máy Đánh Chữ (Typewriter Focus)": "▸ 全画面集中モード (Zen Mode) ＆タイプライターフォーカス",
    "Đi tới nút Zen Mode Tab 1": "Tab 1 の Zen Mode ボタンへ移動",
