    "Load your favorite MP3/WAV files from your device and set exact A-B loop points on the climax you love while writing battle or emotional scenes, or mix rain, campfire, and café sounds synthesized via zero-MB WebAudio.": "端末からお気に入りの MP3/WAV を読み込み、戦闘や感情シーンの執筆中に盛り上がる箇所へ精密な A-B ループを設定したり、0MB WebAudio 合成の雨音・焚き火・カフェ音をミックスできます。",
