    "Khi cần tải bản thảo về máy để biên tập tiếp trong Microsoft Word, gửi cho biên tập viên nhà xuất bản hoặc tải lên Google Docs.": "Microsoft Word で編集を続けたり、出版社の編集者へ送ったり、Google Docs にアップロードするため原稿を保存したいときに。",
