    "Xác nhận 3 thông tin: Tên tác phẩm (gõ mới hoặc chọn từ danh sách đã lưu), Chương mấy (chọn từ Tab 2 hoặc toàn bộ), và Tên tác giả.": "3つの項目を確認します：作品名（新規入力または保存済みリストから選択）、章範囲（Tab 2 から選択または全章）、著者名。",
    "Bấm nút xanh \"Xuất File .DOCX\" — file tải về có phần đầu chuẩn ZIP mở mượt trực tiếp trên mọi bộ gõ văn phòng!": "青い「.DOCX ファイルを書き出す」ボタンを押すと、標準 ZIP ヘッダーを備えたファイルが保存され、あらゆるオフィスソフトで快適に開けます！",
    "Header trong file Word và PDF chỉ đặt canh giữa đúng Tên Tác Phẩm, Footer chỉ đếm số trang đơn giản chứ không chèn ngày giờ rườm rà.": "Word や PDF のヘッダーには作品名のみが中央揃えで入り、フッターには煩雑な日時を入れずシンプルなページ番号のみが表示されます。",
