    "Mô hình thật, Mức tư duy Thấp/Trung/Cao, Hạn mức 5h/Tuần, Enter chạy lệnh & Mode 5": "実モデル、思考レベル 低/中/高、5時間/週枠、Enter 実行＆Mode 5",
    "Cập nhật lũy tiến Ch.1..cuối, Cẩm nang NotebookLM truyện dài & Ma trận nhân vật": "第1章..最終章 累積更新、長編 NotebookLM ガイド＆キャラマトリックス",
