    "3 thanh thu gọn kéo thả tự do, Bi Số 8 2 chế độ tách biệt & Deep-link phát sáng": "自由ドラッグ可能な3つの収納バー、2モード8番ボール Bi＆発光ディープリンク",
    "Xem hướng dẫn từng bước": "ステップ別ガイドを見る",
    "Chỉ đạo AI: Sử dụng kỹ thuật Match Cut điện ảnh: Kết thúc cảnh trước bằng hình ảnh một vật thể (ví dụ: tàn thuốc đỏ rực, giọt nước mưa, vòng xoáy tách cà phê) và mở đầu cảnh này bằng một hình ảnh có hình dáng/chuyển động tương tự ở không gian mới. Ví dụ văn phong: * * * Vệt khói trắng mảnh mai từ đầu điếu thuốc vừa tắt ngấm trong căn phòng thẩm vấn dường như nối dài ra, hòa vào màn sương mù dày đặc đang bao phủ lấy bến cảng phía Đông lúc hai giờ sáng.": "AI指示：映画的な Match Cut 手法を使用してください。前のシーンをある物体のイメージ（例：赤く燻るタバコの灰、雨粒、コーヒーカップの渦）で締めくくり、新しい空間の冒頭を似た形・動きのイメージで繋ぎます。文体例：* * * 取調室で消えたばかりのタバコの先から立ち上る細い白煙が、そのまま伸びていくかのように、午前二時の東埠頭を覆う濃霧へと溶け込んでいった。",
    "e.g., Rooftop café": "例：屋上カフェ",
