    "Viết tiếp ngay sau tiếng chuông ở cuối Chương 3: Trần Minh Khôi và Lệ Băng bước lên sàn gỗ gác chuông tối đen, phát hiện cuộn băng ghi âm nằm sau quả lắc đồng. Giữ đúng xưng hô Tôi/Anh - Cô, tuyệt đối không dùng các cụm sáo ngữ bị cấm và không để lộ bí mật vết sẹo cổ tay quá sớm.": "第3章末尾の鐘の音の直後から書き継ぐ：Trần Minh Khôi と Lệ Băng は真っ暗な鐘楼の木床へ上がり、真鍮製の振り子の裏にあるカセットテープを発見する。「私/彼 - 彼女」の人称・呼称を正確に保ち、禁止常套句は一切使わず、手首の傷跡の秘密を早まって明かさないこと。",
    "Viết một phân đoạn hồi tưởng ngắn (khoảng 300 từ) xen góc nhìn POV ngôi thứ ba theo Trần Minh Khôi khi nhớ về ánh lửa hắt lên mặt kính đồng hồ quả quýt bị vỡ, giữ nguyên bí mật về Giáo sư Hoàng cho chương sau.": "割れた懐中時計のガラスに映る火の光を思い出す Trần Minh Khôi の三人称 POV で短い回想シーン（約300語）を執筆し、Giáo sư Hoàng に関する秘密は次章のために伏せたままにすること。",
    "✍️ [CHẾ ĐỘ 1 — VIẾT BẢN THẢO CHÍNH THỨC] Nhập diễn biến chương truyện, tâm lý nhân vật, bối cảnh không gian hoặc phân cảnh bạn muốn AI triển khai chi tiết (3.000 - 4.000+ từ) tại đây... Ví dụ gợi ý để viết sâu sắc, không tua nhanh: - Cảnh 1 (Mưa khuya ở sảnh ga): Nhân vật A giữ im lặng khi nhận phong thư nặc danh, miêu tả chậm cảm giác lạnh gáy, mùi nước mưa và ánh đèn vàng hắt lên ngón tay run. - Cảnh 2 (Đối thoại căng thẳng): Cuộc chạm trán với Nhân vật B, dùng lời nói ẩn ý chứ chưa vội lật bài ngửa ngay. - Lưu ý: Hệ thống tự động lồng ghép dàn ý đã phát triển ở Chế độ 2 (nếu có) + Story Bible + Mốc chuyển phân cảnh + Ma trận Ai Biết Gì.": "✍️ [モード 1 — 本稿執筆] AIに詳しく描写させたい章の展開、キャラ心理、空間背景、シーンをここに入力してください（3,000〜4,000+ 語）... 駆け足を避ける深い執筆の例：- シーン1（深夜の駅ホールの雨）：人物Aは差出人不明の封筒を受け取り無言のまま、首筋の冷気、雨の匂い、震える指先に落ちる琥珀色の光をじっくり描写する。- シーン2（緊迫の対話）：人物Bとの対峙で、すぐ手の内を明かさず含みのある言葉で応酬する。- 注意：モード2で作成した構成案（ある場合）＋ストーリーバイブル＋場面転換マーカー＋認知マトリックスが自動統合されます。",
    "✅ Duyệt & Chốt Bản Thảo — Tự Động Cập Nhật Story Bible": "✅ 承認して原稿を確定 — ストーリーバイブル自動更新",
    "Đã Duyệt": "承認済み",
    "💡 Sau khi hoàn tất cập nhật Story Bible và chỉ mục chống quên, hệ thống sẽ thông báo thành công ngay trên màn hình (Không hiện cửa sổ đầu ra dư thừa tại đây vì đầu ra đã nằm ở Tab 3 và Story Bible ở Tab 4).": "💡 ストーリーバイブルと記憶保持インデックスの更新が完了すると画面上に成功通知が表示されます（出力は Tab 3、ストーリーバイブルは Tab 4 にあるため、ここに余分な出力枠は出しません）。",
