    "Tin nhắn / Cuộc gọi nửa đêm": "真夜中のメッセージ／着信",
    "Màn hình điện thoại sáng bừng giữa bóng tối với dòng tin ngắn vỏn vẹn ba chữ: \"Đừng mở cửa.\"": "暗闇の中でスマホの画面が光り、そこにはたった一言のメッセージだけが表示されていた。「ドアを開けるな。」",
