    "- Cậu nghĩ suốt ba năm qua... người đang ngồi nói chuyện với cậu mỗi tối thực sự là ai? (Nhân vật B)": "「この 3 年間……毎晩君と向き合って話していた相手が、本当は誰だと思っているんだい？」（キャラクター B）",
