    "Đồng hồ trên tháp chuông vừa điểm mười hai tiếng, và đúng lúc ấy toàn bộ đèn hành lang đồng loạt tắt phụt.": "時計塔の鐘がちょうど十二時を告げたその瞬間、廊下の明かりが一斉に消え落ちた。",
