    "Trung bình (Cân bằng)": "中（バランス）",
    "API Key liên kết đồng bộ thời gian thực tại cả Trung tâm AI, Chat Bi Số 8, Mode 5 và tự động phát hiện 0 điểm cuối live trên tài khoản của bạn.": "連携された API Key は AI ハブ、Bi #8 チャット、Mode 5 でリアルタイム同期され、アカウント上で 0 個のライブエンドポイントを自動検出しました。",
    "🌐 Danh sách Model Gemini Live ↗": "🌐 Gemini Live モデル一覧 ↗",
