    "Gợi ý cho Chế độ 1:": "モード 1 のヒント：",
    "Bạn nên làm rõ bạn muốn AI viết mấy phân cảnh (Càng chia nhỏ càng tốt), mạch truyện nhanh hay chậm, mỗi phân cảnh bao nhiêu từ... Cơ bản như vậy cộng với cái story bible và cái cốt truyện có AI tư vấn bên cạnh nữa là mình thấy oke rồi đó bạn, mình cũng hay viết tới đó thôi hẹ hẹ": "AIにいくつのシーンを書かせたいか（細かく分けるほど良いです）、展開のテンポは速めか遅めか、各シーンを何語くらいにするかを明確に書いておくのがおすすめです…基本的にはそれと横のStory BibleやAIのあらすじ相談があれば十分バッチリで、私も普段そのくらいまでしか書いてません（笑）",
