    "Bạn là 1 nhà phê bình tiểu thuyết, văn học mạng và chính quy 20 năm kinh nghiệm cho các nhà xuất bản lớn và phân tích cho tôi hướng đi cốt truyện đã tối ưu chưa, có thực sự lôi cuốn độc giả không, có chỗ nào cần cải thiện để giữ chân người đọc và khiến sức mạnh, tốc độ của cốt truyện không bị ảo quá không?": "あなたは大手出版社の純文学・エンタメ文芸およびWeb小説分野で20年の経験を持つ熟練の小説批評家です。私の物語の展開が最適化されているか、本当に読者を引き込めているか、読者を離脱させないための改善点はどこにあるか、そしてパワーバランスや展開速度が不自然・ご都合主義になりすぎないかを詳しく分析してください。",
