    "Nhập diễn biến chương truyện, tâm lý nhân vật, bối cảnh không gian hoặc phân cảnh bạn muốn AI triển khai chi tiết (3.000 - 4.000+ từ) tại đây...": "AIに詳細執筆（3,000〜4,000語以上）させたい章の展開・人物心理・舞台・シーン指示をここに入力...",
    "Ví dụ gợi ý để viết sâu sắc, không tua nhanh:": "早送りせず深みのある執筆をする入力例：",
    "- Cảnh 1 (Mưa khuya ở sảnh ga): Nhân vật A giữ im lặng khi nhận phong thư nặc danh, miêu tả chậm cảm giác lạnh gáy, mùi nước mưa và ánh đèn vàng hắt lên ngón tay run.": "- シーン1（深夜の駅ロビーの雨）：匿名封筒を受け取った人物Aの沈黙。うなじの寒気、雨の匂い、震える指先に落ちる黄色い灯りをじっくり描写。",
    "- Cảnh 2 (Đối thoại căng thẳng): Cuộc chạm trán với Nhân vật B, dùng lời nói ẩn ý chứ chưa vội lật bài ngửa ngay.": "- シーン2（緊迫の対話）：人物Bとの邂逅。すぐに切り札を明かさず、含みを持たせた言葉の応酬で進める。",
    "- Lưu ý: Hệ thống tự động lồng ghép dàn ý đã phát triển ở Chế độ 2 (nếu có) + Story Bible + Mốc chuyển phân cảnh + Ma trận Ai Biết Gì.": "- 注意：モード2のプロット案（あれば）＋Story Bible＋シーンマーカー＋情報認知マトリクスを自動統合します。",
    "Bạn có thể liệt kê dàn ý thô ở đây (mỗi gạch đầu dòng là một nhịp sự kiện hoặc ý tưởng bạn đã nghĩ sẵn) để AI chi tiết hóa từng bước mà không tự ý tua nhanh mạch truyện...": "ここに粗いプロット箇条書き（1行1イベント案）を置くと、AIが勝手に早送りせず段階的に詳細化します...",
    "Ví dụ dàn ý thô cực hiệu quả cho Chế độ 2:": "モード2に効果的な粗プロット例：",
    "- Bối cảnh mở đầu chương: Nhân vật chính trở lại căn phòng cũ sau cuộc cãi vã.": "- 冒頭設定：口論の後、主人公が古い部屋へ戻ってくる。",
    "- Ý tưởng muốn khai thác: Tìm thấy một mẩu giấy nhắn cũ hoặc một món đồ làm dấy lên nghi ngờ về người anh trai.": "- 深掘りしたい案：兄への疑念を呼び起こす古いメモや品を見つける。",
    "- Yêu cầu AI: Dựa vào các gạch đầu dòng trên + Story Bible, hãy phát triển chi tiết 3 phương án diễn biến tâm lý chậm rãi cho riêng chương tiếp theo (chưa vội cho nhân vật biết sự thật ngay, giữ nhịp hồi hộp & gài phục bút tinh tế).": "- AIへの指示：上の箇条書き＋Story Bibleを基に、次章単体向けの緩やかな心理展開案を3案詳細化（真相はまだ明かさず緊張感と繊細な伏線を仕込む）。",
