    "Sao chép ngay toàn bộ Prompt Tổng Hợp vào khay nhớ tạm": "マスター統合プロンプト全体を今すぐクリップボードへコピー",
    "Tất cả phục bút đã được xử lý gọn gàng.": "すべての伏線がきれいに回収されました。",
    "21. Luồng Phát Trực Tiếp / PiP, Đồng Bộ Nền YouTube, Cỡ Chữ Toàn Web & Mục #5 Linh Tinh (v46)": "21. 滑らか再生・PiP・YouTube背景同期・全体文字サイズ＆第5おまけコーナー (v46)",
    "NATIVE PIP · BG VIDEO SYNC · SYSTEM FONT SCALE · CHỨC NĂNG LINH TINH": "ネイティブ PiP · 背景映像同期 · システム文字サイズ · おまけ機能ボックス",
    "Nâng cấp phát YouTube mượt mà trên cả Mobile & Desktop (Repeat/A-B không đen màn hình, đồng bộ phát/dừng/tua sang Background, System PiP), Cỡ Chữ Hệ Thống 4 mức & Mục #5 Chức Năng Linh Tinh + Chuỗi điểm danh!": "モバイル・デスクトップ両対応で YouTube 再生を強化（リピート/A-B で黒画面にならない維持再生、再生・停止・シークの背景映像同期、システム PiP）、4段階文字サイズ＆タブ 6 の第5おまけコーナー＋連続出席バッジ！",
    "Khi bấm Lặp video (Repeat) hoặc Lặp đoạn A–B trên YouTube, trình phát giữ nguyên luồng đang chạy không bị đen hay gián đoạn; Video Background tự động khớp Tạm dừng / Phát tiếp / Tua theo khung chính.": "YouTube のリピートや A–B 区間ループを押しても再生ストリームが黒画面や途切れなく維持され、背景動画もメインの一時停止・再生・シークに自動連動します。",
    "Đổi Cỡ Chữ Toàn Web (Nhỏ · Bình thường · To · Rất to) trực tiếp trên Thanh Header hoặc Tab 5/Tab 6; giữ chuỗi Điểm danh 7/21/90/365 ngày nhận huy hiệu Tiểu thuyết gia.": "ヘッダーまたはタブ 5/6 からサイト全体の文字サイズ（小・標準・大・特大）を切替可能。7/21/90/365日連続出席で小説家バッジを解放！",
    "Khám phá Ô #5 \"Chức năng linh tinh\" ở Tab 6 (giữa Ô 4 và Tải App) với SaLưới mini game, kỷ niệm đời đầu & chế độ đa ngôn ngữ đầy đủ kể cả khung Prompt và định dạng ngày giờ bản địa!": "タブ 6（カード 4 とアプリ導入の間）の第5枠「おまけ雑多機能」で SaLưới ミニゲームや初期ファン記念館を楽しめ、プロンプト枠と各国日付形式まで網羅した 6 言語対応も完結！",
    "Repeat / A–B Loop Mượt Mà & Đồng Bộ Nền YouTube (Mod 39/40)": "滑らかなリピート / A–B ループ＆YouTube 背景同期 (Mod 39/40)",
    "Bấm Lặp video hoặc Lặp đoạn A–B nay giữ nguyên khung phát không đen màn hình, đồng thời Video Background luôn Dừng/Chạy/Tua đồng bộ tức thì theo trình phát chính.": "動画リピートや A–B 区間ループを押してもプレーヤー画面が暗転せず維持され、背景映像もメインの一時停止・再生・シークへ即座に同期します。",
    "Cỡ Chữ Toàn Web (4 Mức) & Chuỗi Điểm Danh Huy Hiệu": "4段階サイト文字サイズ＆連続出席バッジ",
    "Tùy chỉnh Cỡ chữ hệ thống (Nhỏ / Bình thường / To / Rất to) đồng bộ Header, Tab 5 & Tab 6; điểm danh giữ chuỗi 7, 21, 90 và 365 ngày để mở khóa các huy hiệu Tiểu thuyết gia.": "ヘッダー・タブ5・タブ6で同期するシステム文字サイズ（小／標準／大／特大）を調整でき、7・21・90・365日連続出席で小説家バッジを解放します。",
    "Mục #5 Chức Năng Linh Tinh & Đa Ngôn Ngữ Toàn Diện": "タブ 6 第5おまけ機能＆全機能フル多言語ローカライズ",
    "Khám phá Ô #5 Chức năng linh tinh ở Tab 6, video hướng dẫn tràn khung chuẩn Mobile/Desktop, cùng dịch đầy đủ 6 ngôn ngữ cho mọi thông báo, khung Prompt & ngày giờ bản địa!": "タブ 6 の第5おまけ機能、スマホ・PC 両対応の全面チュートリアル映像、通知・プロンプト枠・現地日付形式まで網羅した 6 言語対応を体験してください！",
    "v46.0 — Sửa Repeat/A–B Không Đen Video & Đồng Bộ Nền Chặt (Mod 39/40), Cỡ Chữ Toàn Web, Chuỗi Điểm Danh, Ô #5 Linh Tinh & Video Tràn Khung Mobile": "v46.0 — 黒画面ゼロのリピート/A–B＆精密背景同期 (Mod 39/40)、全体文字サイズ、連続出席バッジ、第5おまけ欄＆モバイル全画面動画",
    "Sửa triệt để YouTube Repeat/A–B & Đồng bộ Video Nền (Mod 39/40 + nativePlayer): Không phá hủy hay làm đen iframe khi bật Lặp toàn video / A–B; Video nền đồng bộ tức thì Tạm dừng / Phát / Tua theo cả iframe lẫn luồng HTML5 trực tiếp.": "YouTube リピート/A–B ＆背景映像同期を根本修正（Mod 39/40 + nativePlayer）：全体リピートや A–B 切替時に iframe を破棄・暗転させず、背景映像も iframe と HTML5 直接ストリーム両方の一時停止・再生・シークへ即応追従します。",
    "Video Hướng Dẫn Hiển Thị Trọn Khung Trên Mobile & Fullscreen (Mod 28 + Mod 33): Gỡ triệt để lỗi co góc trên-trái trên điện thoại dọc & cập nhật thêm Phân đoạn #21 (~10:22) bao phủ mọi tính năng mới.": "モバイル＆フルスクリーン対応のチュートリアル動画フル表示（Mod 28 + Mod 33）：縦画面スマホで左上に縮小される不具合を解消し、新機能を網羅した第21章（約10:22）を追加。",
    "Cỡ Chữ Toàn Trang 4 Mức (Nhỏ -> Rất to), Mốc Huy Hiệu Điểm Danh (7/21/90/365 ngày) & Ô #5 Chức Năng Linh Tinh tại Tab 6 tối ưu responsive trên mọi kích thước màn hình.": "ページ全体 4 段階フォントサイズ（小→特大）、連続出席バッジ（7/21/90/365日）、タブ 6 の第5おまけコーナーをあらゆる画面サイズにレスポンシブ最適化。",
    "Hoàn Thiện Đa Ngôn Ngữ 6 Thứ Tiếng (EN / 简体 / 繁體 / KO / JA / VI): Bao gồm cả Prompt Khung 5 Chế độ, thông báo góc thu/mở, thẻ trạng thái & định dạng ngày giờ thực tế từng quốc gia (YY/MM/DD, MM/DD/YY, dd/mm/yy).": "6 言語フルローカライズ完成（EN / 简体 / 繁體 / KO / JA / VI）：5 モードのプロンプト枠、開閉トースト通知、ステータス表示、各国の実際の日付形式（YY/MM/DD・MM/DD/YY・dd/mm/yy）まで完備。",
