    "🔄 Luồng phát công cộng đang bị YouTube giới hạn — Đang tự động kết nối lại liên tục đến khi phát nền được!": "🔄 公開ストリームがYouTubeに制限されています — バックグラウンド再生できるまで自動再接続を継続中！",
