    "📺 Máy chủ trích xuất âm thanh tạm bận — phát trực tiếp bằng Iframe youtube-nocookie.com tại Mục 5.": "📺 音声抽出サーバーが一時的に混雑しています — タブ5で youtube-nocookie.com の Iframe を直接再生します。",
    "🎬 Video Hướng Dẫn Chi Tiết Toàn Bộ Tính Năng (~12+ Phút, Song Ngữ Ngoài Khung Hình) & Nhật Ký Mới Nhất": "🎬 全機能の詳細チュートリアル動画（約12分以上・枠外バイリンガル字幕）＆最新更新履歴",
    "📑 25 Mốc Chức Năng Chi Tiết (~12+ Phút) · Toàn Bộ Tính Năng Mới (Chạm Để Tua Tới)": "📑 全25チャプター詳細（約12分以上）· 全新機能解説（タップで移動）",
    "22. YouTube Tự Động Nối Hạ Tầng MP3 Mục 3 Để Phát Nền & Hộp Thoại Ưu Tiên Âm Thanh (Mod 39 & 21)": "22. YouTube音声を項目3 MP3基盤へ自動連携しバックグラウンド再生＆優先確認ダイアログ (Mod 39 & 21)",
    "MỤC 5 ➔ MỤC 3 MP3 NỀN · ĐỒNG BỘ 2 CHIỀU · XUNG ĐỘT THÔNG MINH": "項目5 ➔ 項目3 MP3背景 · 双方向同期 · スマート音声確認",
    "Mặc định phát âm thanh YouTube qua hạ tầng MP3 Mục 3 để thoát trình duyệt/tắt màn hình vẫn nghe ổn định; đồng bộ Tạm dừng/Phát/Tua 2 chiều, tự dừng bài cũ khi đổi video & hỏi xác nhận khi bật MP3 máy.": "初期設定でYouTube音声を項目3のMP3基盤で再生し、アプリ切替や画面オフでも安定再生。再生・停止・シークの双方向同期、動画切替時の旧音声停止、ローカルMP3再生時の確認ポップアップに対応。",
    "Chọn bất kỳ video YouTube nào ở Tab 5 Ô #5: khung hình lên ngay đồng thời luồng tiếng tự động nối thẳng sang động cơ MP3 Mục 3 (nghe nền cực ổn định khi chuyển ứng dụng hoặc khóa màn hình).": "タブ5枠#5で任意のYouTube動画を選ぶと映像が即表示され、音声は項目3のMP3エンジンへ自動接続されるため、他アプリ切替やロック画面でも安定してバックグラウンド再生できます。",
    "Mọi thao tác Dừng / Phát tiếp / Tua ±10s / Kéo thanh thời gian đều đồng bộ 2 chiều theo thời gian thực giữa khung hình YouTube và âm thanh Mục 3; đổi sang video khác sẽ tự tắt tiếng video cũ.": "停止・再生・±10秒シーク・タイムライン操作はYouTube映像と項目3音声でリアルタイム双方向同期され、別動画へ切り替えると前の音声は自動停止します。",
    "Nếu bạn đang mở video YouTube mà bấm nghe một bản nhạc MP3 riêng trên máy tại Mục 3, hộp thoại sẽ hỏi xác nhận có tắt YouTube để chuyển sang nghe bản nhạc đó hay không.": "YouTube再生中に項目3で端末内のMP3曲を再生すると、YouTubeを停止してその曲へ切り替えるか確認ダイアログが表示されます。",
    "23. Tự Động Lưu 3 Tầng Mỗi 2 Giây & Khi Đổi Trạng Thái: Văn Bản, Gấp/Mở Mục, Nhạc & Tab": "23. 2秒ごとの3層自動保存＆状態変更時の即時保存：本文・開閉・音楽・タブ位置",
    "TỰ LƯU MỖI 2 GIÂY · LƯU GẤP/MỞ KHỐI · LƯU TAB & VỊ TRÍ CUỘN": "2秒自動保存 · 折りたたみ保存 · タブ＆スクロール位置復元",
    "Mọi thay đổi như gõ/xóa chữ, thu gọn hay mở rộng bảng, dừng/tắt YouTube hay MP3, chọn ngôn ngữ/cỡ chữ và vị trí Tab cuối đều tự lưu sau tối đa 2 giây & lúc rời trang.": "文字入力や削除、パネルの折りたたみ・展開、YouTubeやMP3の停止状態、言語・文字サイズ、最後のタブ位置まですべて最大2秒以内および終了時に自動保存されます。",
    "Gõ hoặc xóa chữ trong bản thảo Tab 1: bộ tự lưu 3 tầng (IndexedDB + Két sắt + Thư mục máy tính) cập nhật tự động sau 2 giây và lưu ngay trước khi đóng tab.": "タブ1の原稿で文字を入力または削除すると、3層自動保存（IndexedDB＋緊急保管庫＋PCフォルダ）が2秒後およびタブを閉じる直前に自動保存します。",
    "Mọi thao tác Thu gọn / Mở rộng các bảng chức năng ở Tab 1, 2, 5, 6 đều được ghi nhớ y nguyên cho lần mở lại kế tiếp.": "タブ1・2・5・6の各パネルの折りたたみ・展開状態はすべて記憶され、次回アクセス時もそのまま復元されます。",
    "Trạng thái đang phát hoặc đã tắt Video YouTube / Nhạc MP3, cũng như Tab đang mở & vị trí cuộn cuối cùng trước khi rời trang đều được khôi phục chính xác.": "YouTube動画やMP3音楽の再生・停止状態、退出前のアクティブタブとスクロール位置も正確に復元されます。",
    "24. Cổng Khởi Đầu Tinh Gọn 2 Bước, Cuộn Mượt PC/Mobile & Bảng Thông Báo Từ Google Sheet (Mod 34)": "24. シンプル2ステップ入口ゲート、PC/スマホ快適スクロール＆Google Sheet通知ポップアップ (Mod 34)",
    "CỔNG VÀO GỌN SẠCH · CUỘN MƯỢT PC/MOBILE · POPUP THÔNG BÁO GOOGLE SHEET": "すっきり入口ゲート · PC/スマホ滑らかスクロール · Google Sheet通知",
    "Rút gọn nút \"Mở Google Studio lấy mã\", lược bỏ phần chọn thư mục thừa, cuộn trọn từ trên xuống dưới trên laptop & điện thoại cùng popup thông báo từ Google Sheet sau khi vào.": "「Google Studioからキー取得」ボタンを簡潔化し、冗長なフォルダ選択を削除。PCとスマホ両方で最下部まで滑らかにスクロールでき、入室後にGoogle Sheetの予約通知が表示されます。",
    "Tại Cổng Kết Nối trên cả Laptop và Điện thoại, thanh cuộn mượt tới tận đáy để nhập API Key (\"Mở Google Studio lấy mã\") và bấm chọn Thư mục làm việc một bước duy nhất.": "PCでもスマホでも入口ゲートを最下部まで滑らかにスクロールでき、「Google Studioからキー取得」でAPI Keyを入力し、1ステップで作業フォルダを選択できます。",
    "Các nút điều khiển YouTube được tối ưu chống rung giật/nháy sáng khi đang chạy hay đồng bộ.": "YouTubeの再生操作ボタンのちらつき・ガタつきを完全に解消しました。",
