    "[NHỊP CẢNH SLOW-BURN]: Dành thời gian cho bầu không khí thấm sâu, miêu tả chi tiết không gian vật lý, kéo dài sự dò xét giữa các nhân vật trước khi tung ra mảnh thông tin quan trọng.": "[シーンテンポ・スローバーン]：場の空気をじっくり浸透させ、空間描写を丁寧に描き込み、重要情報を明かす前に人物同士の探り合いを十分に溜めてください。",
    "[NHỊP CẢNH CAO TRÀO]: Tăng tốc độ chuyển động, ưu tiên câu ngắn gãy gọn, truyền tải tiếng tim đập, hơi thở dồn dập và phản xạ chớp nhoáng trong không gian hẹp.": "[シーンテンポ・クライマックス]：動きを加速させ短く歯切れのよい文を多用し、閉鎖空間での鼓動・荒い呼吸・刹那の反射神経を緊迫感たっぷりに描いてください。",
